def wl(reg,l,k,ref):
    a=T[f'{reg}|{l}|{k}']; return a,a['amp']/J[ref][reg][0],a['err']/J[ref][reg][0]
def s(reg,l,k,ref):
    a,r,e=wl(reg,l,k,ref); return f'{r:.4f}+-{e:.4f} ({a["snr"]:.1f}sig, {a["cls"]})' if a['cls']!='lim' else f'<{3*a["err"]/J[ref][reg][0]:.4f} (3sig; fit {r:.4f}+-{e:.4f})'
